import React, { useContext, useState } from 'react';
import Navbar from '../Components/Navbar';
import { apiValue } from '../Data/AllData';
import { CartProvider, useCart } from 'react-use-cart';
import { Link } from 'react-router';
import { motion, MotionConfig } from 'framer-motion';
import Footer from '../Components/Footer';

const PAGE_SIZE = 6;

const btnBase = `group relative inline-flex h-10 min-w-0 flex-1 items-center justify-center gap-2 overflow-hidden whitespace-nowrap rounded-full
  border border-[#B08D57]/50
  bg-gradient-to-br from-[#150c05] to-[#150c05] px-3
  text-[11px] font-semibold uppercase leading-none tracking-[0.12em] text-[#F1E7D0]
  shadow-[0_5px_14px_rgba(0,0,0,0.6),inset_0_1px_0_rgba(191,232,210,0.12)]
  transition-all duration-300 ease-out
  active:translate-y-0 active:scale-[0.97]`;

const cartBtn = `${btnBase}
  hover:-translate-y-0.5 hover:border-[#B08D57] hover:text-[#B08D57]`;

const detailsBtn = `${btnBase}
  hover:-translate-y-0.5 hover:border-[#B08D57]
  hover:text-[#B08D57]
  hover:shadow-[0_8px_20px_rgba(0,0,0,0.6),0_0_22px_rgba(176,141,87,0.35),inset_0_1px_0_rgba(255,235,200,0.18)]
  focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#B08D57]`;

function ProductCard({ item, index }) {
  const { addItem } = useCart();
  const image = item.images?.[0] ?? item.thumbnail;
  const outOfStock = !(item.stock > 0);

  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.15 }}
      transition={{ duration: 0.4, ease: 'easeOut', delay: (index % PAGE_SIZE) * 0.04 }}
      className="w-full overflow-hidden rounded-lg border border-[#B08D57]/40 bg-[#F1E7D0] shadow-xl"
    >
      {/* Image: clickable, goes to details */}
      <Link to={`/details/${item.id}`} className="block bg-[#E8DABB] p-4">
        <div className="overflow-hidden rounded-md border border-[#B08D57]/40 bg-white/60 p-2 shadow-md">
          <img
            src={image}
            alt={item.title}
            loading="lazy"
            className="aspect-[4/3] w-full cursor-pointer object-cover transition-transform duration-500 hover:scale-105"
          />
        </div>
      </Link>

      {/* Info */}
      <div className="space-y-3 p-6">
        <span className="block text-[10px] font-bold uppercase tracking-[0.25em] text-[#2A1A1A]/50">
          {item.category}
        </span>
        <h3 className="font-serif-display text-xl font-medium leading-tight tracking-tight text-[#2A1A1A]">
          {item.title}
        </h3>
        <div className="h-px w-12 bg-[#B08D57]" />

        <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
          <span className="text-2xl font-bold text-[#2A1A1A]">${item.price}</span>
          <span className="text-sm text-[#2A1A1A]/70">★ {item.rating}</span>
          <span
            className={`text-[10px] font-bold uppercase tracking-[0.2em] ${
              outOfStock ? 'text-[#B3121F]' : 'text-green-700'
            }`}
          >
            {outOfStock ? 'Out of stock' : item.stock <= 5 ? `Only ${item.stock} left` : 'In stock'}
          </span>
        </div>

        <div className="flex w-full items-center gap-3 pt-2">
          <button
            type="button"
            disabled={outOfStock}
            className={`${cartBtn} disabled:opacity-40`}
            onClick={() => addItem(item)}
          >
            <svg
              className="h-[14px] w-[14px] shrink-0 opacity-85"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.8"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="M6 8h12l-1 11a2 2 0 0 1-2 1.8H9a2 2 0 0 1-2-1.8L6 8z" />
              <path d="M9 8V6.5a3 3 0 0 1 6 0V8" />
            </svg>
            <span className="text-[10px]">Add to Cart</span>
          </button>

          <Link to={`/details/${item.id}`} className={detailsBtn}>
            <span className="relative">Details</span>
            <span className="relative text-[10px] opacity-70">✦</span>
          </Link>
        </div>
      </div>
    </motion.div>
  );
}

function ProductsGrid() {
  const data = useContext(apiValue) ?? [];
  const [category, setCategory] = useState('All');
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE);

  const categories = ['All', ...new Set(data.map((item) => item.category))];

  const filteredItems =
    category === 'All' ? data : data.filter((item) => item.category === category);

  const visibleItems = filteredItems.slice(0, visibleCount);
  const hasMore = visibleCount < filteredItems.length;

  const handleCategoryChange = (name) => {
    setCategory(name);
    setVisibleCount(PAGE_SIZE);
  };

  return (
    <div className="products-page">
      <div className="filter-bar" role="group" aria-label="Filter by category">
        {categories.map((name) => (
          <button
            key={name}
            type="button"
            className={`filter-btn ${category === name ? 'is_active' : ''}`}
            aria-pressed={category === name}
            onClick={() => handleCategoryChange(name)}
          >
            {name}
          </button>
        ))}
      </div>

      {filteredItems.length === 0 ? (
        <p className="empty-state">No products found in this category.</p>
      ) : (
        <>
          <div className="products-grid">
            {visibleItems.map((item, i) => (
              <ProductCard key={`${category}-${item.id}`} item={item} index={i} />
            ))}
          </div>

          {hasMore && (
            <div className="flex justify-center py-10">
              <button
                type="button"
                onClick={() => setVisibleCount((c) => c + PAGE_SIZE)}
                className="rounded-full border border-[#B08D57]/50 bg-[#150c05] px-10 py-3
                  text-xs font-semibold uppercase tracking-[0.15em] text-[#F1E7D0]
                  shadow-[0_5px_14px_rgba(0,0,0,0.6)] transition-all duration-300
                  hover:-translate-y-0.5 hover:border-[#B08D57] hover:text-[#B08D57]
                  active:scale-[0.97]"
              >
                Load More
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

function AllProducts() {
  return (
    <MotionConfig reducedMotion="user">
      <CartProvider>
        <Navbar />
        <ProductsGrid />
        <Footer />
      </CartProvider>
    </MotionConfig>
  );
}

export default AllProducts;