function useIsDesktop() {
  const [isDesktop, setIsDesktop] = useState(false)
  useEffect(() => {
    const mq = window.matchMedia('(min-width: 768px)')
    const update = () => setIsDesktop(mq.matches)
    update()
    mq.addEventListener('change', update)
    return () => mq.removeEventListener('change', update)
  }, [])
  return isDesktop
}

function CardSection() {
  const [activeCard, setActiveCard] = useState(null)
  const ref = useRef(null)
  const inView = useInView(ref, { once: true, amount: 0.35 })
  const isDesktop = useIsDesktop()
  const reduce = useReducedMotion()

  return (
    <section
      ref={ref}
      className="relative mx-auto flex min-h-[420px] w-full max-w-3xl select-none items-center justify-center"
    >
      {/* هالة ذهبية ناعمة ورا الكروت */}
      <motion.div
        aria-hidden="true"
        className="pointer-events-none absolute h-72 w-72 rounded-full bg-[#B08D57]/10 blur-3xl"
        initial={{ opacity: 0 }}
        animate={{ opacity: inView ? 1 : 0 }}
        transition={{ duration: 1.5 }}
      />

      {cards.map((card, i) => {
        const isActive = activeCard === card.id
        const x = isDesktop ? card.x.md : card.x.sm

        const hidden = { x: 0, y: 50, rotate: 0, scale: 0.85, opacity: 0 }
        const rest = { x, y: card.y, rotate: card.rotate, scale: 1, opacity: 1 }
        const active = { x, y: card.y - 24, rotate: 0, scale: 1.1, opacity: 1 }

        return (
          <motion.div
            key={card.id}
            role="button"
            tabIndex={0}
            aria-pressed={isActive}
            onClick={() => setActiveCard(isActive ? null : card.id)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault()
                setActiveCard(isActive ? null : card.id)
              }
            }}
            initial={hidden}
            animate={inView ? (isActive ? active : rest) : hidden}
            whileHover={reduce ? undefined : { y: card.y - 18, rotate: 0, scale: 1.07, zIndex: 50 }}
            whileTap={{ scale: 1.03 }}
            transition={
              reduce
                ? { duration: 0 }
                : { type: 'spring', stiffness: 90, damping: 14, delay: inView && !activeCard ? i * 0.12 : 0 }
            }
            style={{ zIndex: isActive ? 50 : card.z }}
            className={`absolute cursor-pointer border bg-[#F1E7D0] p-3 pb-8 text-[#2A1A1A] shadow-2xl outline-none focus-visible:ring-2 focus-visible:ring-[#B08D57] ${
              card.center ? 'w-48 md:w-56' : 'w-44 md:w-52'
            } ${isActive ? 'border-[#B08D57] shadow-[0_20px_50px_rgba(0,0,0,0.6),0_0_30px_rgba(176,141,87,0.35)]' : 'border-[#B08D57]/40'}`}
          >
            <img
              src={card.img}
              alt={card.title}
              loading="lazy"
              draggable={false}
              className="aspect-square w-full object-cover"
            />
            <div
              className={`font-serif-editorial mt-3 text-left uppercase tracking-widest ${
                card.center ? 'text-xs font-bold text-[#2A1A1A]' : 'text-[10px] text-[#2A1A1A]/60'
              }`}
            >
              {card.title}
            </div>
          </motion.div>
        )
      })}
    </section>
  )
}

export default CardSection