import React, { useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import { motion, useInView } from 'framer-motion'
import { apiValue } from '../Data/AllData'

const arrowBtn =
  'flex h-11 w-11 items-center justify-center rounded-full border border-[#B08D57]/60 bg-[#150c05]/80 text-lg text-[#F1E7D0] ' +
  'backdrop-blur-sm transition-all duration-300 hover:border-[#D4B06A] hover:bg-[#B08D57] hover:text-[#141010] active:scale-90 ' +
  'disabled:cursor-not-allowed disabled:opacity-30 disabled:hover:border-[#B08D57]/60 disabled:hover:bg-[#150c05]/80 disabled:hover:text-[#F1E7D0]'

const AUTOPLAY_MS = 3500

const fadeUp = {
  hidden: { opacity: 0, y: 30, filter: 'blur(6px)' },
  show: {
    opacity: 1,
    y: 0,
    filter: 'blur(0px)',
    transition: { duration: 0.9, ease: [0.22, 1, 0.36, 1] },
  },
}

const trackVariants = {
  hidden: {},
  show: { transition: { staggerChildren: 0.12, delayChildren: 0.2 } },
}

const cardVariants = {
  hidden: { opacity: 0, y: 50, scale: 0.94 },
  show: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.8, ease: [0.22, 1, 0.36, 1] },
  },
}

function Carousel({ title = 'Featured Relics', subtitle = 'Our most loved pieces', limit = 8 }) {
  const data = useContext(apiValue) ?? []
  const sectionRef = useRef(null)
  const trackRef = useRef(null)
  const visible = useInView(sectionRef, { amount: 0.2 })
  const [edge, setEdge] = useState({ start: true, end: false })
  const [progress, setProgress] = useState(0)
  const [paused, setPaused] = useState(false)

  const items = useMemo(
    () =>
      [...data]
        .filter((p) => p.stock > 0)
        .sort((a, b) => b.rating - a.rating)
        .slice(0, limit),
    [data, limit]
  )

  const updateEdges = useCallback(() => {
    const el = trackRef.current
    if (!el) return
    const max = el.scrollWidth - el.clientWidth
    setEdge({
      start: el.scrollLeft <= 4,
      end: el.scrollLeft + el.clientWidth >= el.scrollWidth - 4,
    })
    setProgress(max > 0 ? el.scrollLeft / max : 0)
  }, [])

  useEffect(() => {
    updateEdges()
    window.addEventListener('resize', updateEdges)
    return () => window.removeEventListener('resize', updateEdges)
  }, [updateEdges, items.length])

  const scrollByCard = useCallback((dir) => {
    const el = trackRef.current
    if (!el) return
    const card = el.querySelector('[data-card]')
    const step = card ? card.offsetWidth + 20 : el.clientWidth * 0.8
    el.scrollBy({ left: dir * step, behavior: 'smooth' })
  }, [])

  // Autoplay: بس لما السكشن ظاهر على الشاشة ومفيش hover
  useEffect(() => {
    if (paused || !visible || items.length < 2) return
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return

    const id = setInterval(() => {
      const el = trackRef.current
      if (!el) return
      const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 4
      if (atEnd) el.scrollTo({ left: 0, behavior: 'smooth' })
      else scrollByCard(1)
    }, AUTOPLAY_MS)

    return () => clearInterval(id)
  }, [paused, visible, items.length, scrollByCard])

  if (items.length === 0) return null

  return (
    <section
      ref={sectionRef}
      className="w-full px-4 py-20 sm:px-6 md:py-28"
      aria-label={title}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
      onTouchStart={() => setPaused(true)}
      onTouchEnd={() => setPaused(false)}
    >
      <div className="mx-auto max-w-6xl">
        {/* Header + arrows */}
        <motion.div
          variants={{ hidden: {}, show: { transition: { staggerChildren: 0.15 } } }}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true, amount: 0.5 }}
          className="mb-8 flex items-end justify-between gap-4"
        >
          <div>
            <motion.p
              variants={fadeUp}
              className="text-[11px] font-semibold uppercase tracking-[0.4em] text-[#B08D57]"
            >
              ✦ {subtitle}
            </motion.p>
            <motion.h2
              variants={fadeUp}
              className="font-serif-display mt-2 text-3xl uppercase tracking-[0.15em] text-[#F1E7D0] md:text-4xl"
            >
              {title}
            </motion.h2>
          </div>

          <motion.div variants={fadeUp} className="hidden gap-3 sm:flex">
            <button
              type="button"
              aria-label="Previous"
              className={arrowBtn}
              disabled={edge.start}
              onClick={() => scrollByCard(-1)}
            >
              ←
            </button>
            <button
              type="button"
              aria-label="Next"
              className={arrowBtn}
              disabled={edge.end}
              onClick={() => scrollByCard(1)}
            >
              →
            </button>
          </motion.div>
        </motion.div>

        {/* Track */}
        <motion.div
          ref={trackRef}
          onScroll={updateEdges}
          variants={trackVariants}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true, amount: 0.2 }}
          className="flex snap-x snap-mandatory gap-5 overflow-x-auto scroll-smooth pb-6
                     [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        >
          {items.map((item) => (
            <motion.div
              key={item.id}
              data-card
              variants={cardVariants}
              className="w-[72%] shrink-0 snap-start py-4 sm:w-[44%] md:w-[31%] lg:w-[23.5%]"
            >
              <Link
                to={`/details/${item.id}`}
                className="group block rounded-xl border border-[#B08D57]/40 bg-[#f1e7d0] p-2 pb-5 text-[#2A1A1A]
                           shadow-xl transition-all duration-300 hover:-translate-y-2.5 hover:border-[#B08D57]
                           hover:shadow-[0_14px_30px_rgba(0,0,0,0.5)]"
              >
                <div className="relative aspect-square overflow-hidden rounded-lg bg-white/60">
                  <img
                    src={item.images?.[0] ?? item.thumbnail}
                    alt={item.title}
                    loading="lazy"
                    className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                  {item.discountPercentage > 0 && (
                    <span className="absolute left-2 top-2 rounded bg-[#150c05]/85 px-2 py-1 text-[10px] font-bold tracking-wider text-[#F1E7D0]">
                      -{Math.round(item.discountPercentage)}%
                    </span>
                  )}
                </div>

                <div className="mt-4 space-y-1 px-1 text-left">
                  <p className="text-[10px] uppercase tracking-[0.2em] text-[#2A1A1A]/50">
                    {item.category}
                  </p>
                  <h3 className="font-serif-display text-lg font-medium leading-tight">
                    {item.title}
                  </h3>
                  <div className="flex items-center justify-between pt-2">
                    <span className="text-base font-bold">${item.price}</span>
                    <span className="text-[10px] uppercase tracking-[0.2em] text-[#B3121F] transition-transform duration-300 group-hover:translate-x-1">
                      View ✦
                    </span>
                  </div>
                </div>
              </Link>
            </motion.div>
          ))}
        </motion.div>

        {/* Progress bar */}
        <div className="mx-auto mt-2 h-px w-40 overflow-hidden bg-[#B08D57]/20">
          <div
            className="h-full origin-left bg-[#B08D57] transition-transform duration-300"
            style={{ transform: `scaleX(${Math.max(progress, 0.08)})` }}
          />
        </div>
      </div>
    </section>
  )
}

export default Carousel