import React, { useRef } from 'react'
import { Link } from 'react-router'
import { motion, useReducedMotion, useScroll, useTransform } from 'framer-motion'

const container = {
  hidden: {},
  show: { transition: { staggerChildren: 0.25, delayChildren: 0.4 } },
}

const item = {
  hidden: { opacity: 0, y: 30, filter: 'blur(8px)' },
  show: {
    opacity: 1,
    y: 0,
    filter: 'blur(0px)',
    transition: { duration: 1, ease: [0.22, 1, 0.36, 1] },
  },
}

// غبار ذهبي: قيم ثابتة عشان الشكل ما يتغيرش مع كل render
const dust = Array.from({ length: 18 }, (_, i) => ({
  left: `${(i * 37) % 100}%`,
  top: `${(i * 53) % 100}%`,
  size: 2 + (i % 3),
  duration: 7 + (i % 5) * 2,
  delay: (i % 6) * 0.8,
}))

function Hero() {
  const reduce = useReducedMotion()
  const sectionRef = useRef(null)

  // parallax: القطعة بتنزل أبطأ من الصفحة وتختفي تدريجيًا
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ['start start', 'end start'],
  })
  const pieceY = useTransform(scrollYProgress, [0, 1], [0, 160])
  const pieceOpacity = useTransform(scrollYProgress, [0, 0.8], [1, 0])

  return (
    <section ref={sectionRef} className="relative min-h-screen overflow-hidden">
      {/* الخلفية */}
      <div className="absolute inset-0 z-0">
        <motion.img
          src="/hero.jpg"  /* حطي هنا رابط صورتك */
          alt=""
          className="h-full w-full object-cover object-center"
          initial={{ scale: reduce ? 1 : 1.15 }}
          animate={{ scale: 1 }}
          transition={{ duration: 14, ease: 'easeOut' }}
        />
        <div className="absolute inset-0 bg-gradient-to-b from-[#160d06]/80 via-[#160d06]/50 to-[#160d06]/90" />
      </div>

      {/* اللوكيت: ورا الكلام، بيطفو وبيعمل parallax */}
      <motion.div
        aria-hidden="true"
        style={reduce ? undefined : { y: pieceY, opacity: pieceOpacity }}
        className="pointer-events-none absolute inset-0 z-[1] flex items-center justify-center"
      >
        <motion.div
          className="w-[60vw] max-w-[320px] select-none drop-shadow-[0_20px_60px_rgba(176,141,87,0.45)]"
          initial={{ opacity: 0, scale: 0.85 }}
          animate={
            reduce
              ? { opacity: 0.5, scale: 1 }
              : { opacity: 0.5, scale: 1, y: [0, -18, 0], rotate: [-3, 3, -3] }
          }
          transition={{
            opacity: { duration: 2, delay: 0.3 },
            scale: { duration: 2, delay: 0.3, ease: 'easeOut' },
            y: { duration: 7, repeat: Infinity, ease: 'easeInOut' },
            rotate: { duration: 9, repeat: Infinity, ease: 'easeInOut' },
          }}
        >
          <svg
            viewBox="0 0 200 270"
            fill="none"
            stroke="#D4B27A"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {/* السلسلة */}
            <circle cx="100" cy="18" r="9" />
            <path d="M100 27 V50" />
            {/* اللوكيت */}
            <path d="M100 250 C28 182 14 118 52 82 C78 58 100 76 100 98 C100 76 122 58 148 82 C186 118 172 182 100 250 Z" />
            {/* الإطار الداخلي */}
            <path
              d="M100 222 C46 168 36 122 62 98 C80 82 100 94 100 112 C100 94 120 82 138 98 C164 122 154 168 100 222 Z"
              opacity="0.6"
            />
            {/* نجمة في النص */}
            <path
              d="M100 118 L106 140 L128 146 L106 152 L100 174 L94 152 L72 146 L94 140 Z"
              fill="#D4B27A"
              fillOpacity="0.25"
            />
          </svg>
        </motion.div>
      </motion.div>

      {/* غبار ذهبي طافي */}
      {!reduce && (
        <div className="pointer-events-none absolute inset-0 z-[2]">
          {dust.map((d, i) => (
            <motion.span
              key={i}
              className="absolute rounded-full bg-[#D4B27A]"
              style={{ left: d.left, top: d.top, width: d.size, height: d.size }}
              animate={{ y: [0, -60, 0], opacity: [0, 0.6, 0] }}
              transition={{
                duration: d.duration,
                delay: d.delay,
                repeat: Infinity,
                ease: 'easeInOut',
              }}
            />
          ))}
        </div>
      )}

      {/* المحتوى */}
      <motion.div
        variants={container}
        initial="hidden"
        animate="show"
        className="relative z-10 mx-auto flex min-h-screen max-w-4xl flex-col items-center justify-center px-6 pt-24 text-center md:pt-32"
      >
        <motion.p
          variants={item}
          className="mb-6 text-[11px] font-semibold uppercase tracking-[0.5em] text-[#B08D57]"
        >
          ✦ Lilith &amp; Lace ✦
        </motion.p>

        <motion.h1
          variants={item}
          className="font-serif-display text-3xl uppercase leading-[1.25] tracking-[0.15em] text-[#D4B27A] drop-shadow-2xl sm:text-5xl md:text-6xl"
        >
          Treasures of a <br />
          Darker Age
        </motion.h1>

        <motion.div
          variants={{
            hidden: { scaleX: 0, opacity: 0 },
            show: { scaleX: 1, opacity: 1, transition: { duration: 1, ease: 'easeOut' } },
          }}
          className="my-8 h-px w-24 origin-center bg-[#B08D57]"
        />

        <motion.p
          variants={item}
          className="font-serif-editorial max-w-xl text-balance text-base font-light italic leading-relaxed text-[#F1E7D0] drop-shadow-md sm:text-lg md:text-xl"
        >
          Antique-inspired jewelry for those who find beauty in the dark. Every piece carries a story older than time.
        </motion.p>

        <motion.div variants={item} className="mt-10">
          <Link
            to="/products"
            className="group inline-flex items-center gap-3 rounded-full border border-[#B08D57]/60 bg-[#150c05]/70 px-9 py-4 text-xs font-semibold uppercase tracking-[0.25em] text-[#F1E7D0] backdrop-blur-sm transition-all duration-300 hover:-translate-y-0.5 hover:border-[#B08D57] hover:text-[#B08D57] hover:shadow-[0_0_28px_rgba(176,141,87,0.35)]"
          >
            Browse the collection
            <span className="transition-transform duration-300 group-hover:translate-x-1">→</span>
          </Link>
        </motion.div>
      </motion.div>

      {/* مؤشر scroll */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 2.2, duration: 1 }}
        className="absolute bottom-8 left-1/2 z-10 flex -translate-x-1/2 flex-col items-center gap-2"
      >
        <span className="text-[10px] uppercase tracking-[0.4em] text-[#B08D57]/80">Scroll</span>
        <motion.span
          className="block h-10 w-px origin-top bg-[#B08D57]"
          animate={reduce ? {} : { scaleY: [0, 1, 0], originY: [0, 0, 1] }}
          transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' }}
        />
      </motion.div>
    </section>
  )
}

export default Hero