import React, { useContext, useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { CartProvider, useCart } from 'react-use-cart'
import Navbar from '../Components/Navbar'
import Footer from '../Components/Footer'
import { apiValue } from '../Data/AllData'

const primaryBtn =
  'group relative inline-flex h-12 min-h-[3rem] w-full shrink-0 items-center sm:flex-1 justify-center gap-2 overflow-hidden whitespace-nowrap rounded-full ' +
  'border border-[#B08D57]/50 bg-[#150c05] px-8 ' +
  'text-[11px] font-semibold uppercase tracking-[0.15em] text-[#F1E7D0] ' +
  'shadow-[0_5px_14px_rgba(0,0,0,0.6)] transition-all duration-300 ease-out ' +
  'hover:-translate-y-0.5 hover:border-[#B08D57] hover:text-[#B08D57] ' +
  'hover:shadow-[0_8px_20px_rgba(0,0,0,0.6),0_0_22px_rgba(176,141,87,0.35)] ' +
  'active:translate-y-0 active:scale-[0.97] ' +
  'disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:translate-y-0 ' +
  'disabled:hover:border-[#B08D57]/50 disabled:hover:text-[#F1E7D0]'

const secondaryBtn =
  'group relative inline-flex h-12 min-h-[3rem] w-full shrink-0 items-center sm:flex-1 justify-center gap-2 overflow-hidden whitespace-nowrap rounded-full ' +
  'border border-[#B08D57]/50 bg-[#150c05] px-8 ' +
  'text-[11px] font-semibold uppercase tracking-[0.15em] text-[#F1E7D0] ' +
  'shadow-[0_5px_14px_rgba(0,0,0,0.6)] transition-all duration-300 ease-out ' +
  'hover:-translate-y-0.5 hover:border-[#B08D57] hover:text-[#B08D57] ' +
  'hover:shadow-[0_8px_20px_rgba(0,0,0,0.6),0_0_22px_rgba(176,141,87,0.35)] ' +
  'active:translate-y-0 active:scale-[0.97]'
function PageShell({ children }) {
  return (
    <div>
      <Navbar />
      {children}
      <Footer />
    </div>
  )
}

function Details() {
  const { id } = useParams()
  const data = useContext(apiValue) ?? []
  const { addItem } = useCart()
  const [activeImg, setActiveImg] = useState(0)
  const [added, setAdded] = useState(false)

  // brief "Added" confirmation on the button
  useEffect(() => {
    if (!added) return
    const t = setTimeout(() => setAdded(false), 1600)
    return () => clearTimeout(t)
  }, [added])

  const product = data.find((item) => String(item.id) === String(id))

  if (data.length === 0) {
    return (
      <PageShell>
        <div className="flex min-h-screen items-center justify-center px-4 pt-28 text-[#F1E7D0]/70">
          Loading...
        </div>
      </PageShell>
    )
  }

  if (!product) {
    return (
      <PageShell>
        <div className="flex min-h-screen flex-col items-center justify-center gap-6 px-4 pt-28 text-center text-[#F1E7D0]">
          <p className="font-serif-display text-2xl">This relic could not be found.</p>
          <Link to="/products" className="font-gothic text-xs uppercase tracking-[0.2em] text-[#B08D57] hover:text-white">
            ← Back to Products
          </Link>
        </div>
      </PageShell>
    )
  }

  const gallery = product.images?.length ? product.images : [product.thumbnail]
  const mainImage = gallery[activeImg] ?? gallery[0]
  const outOfStock = !(product.stock > 0)
  const info = [product.warrantyInformation, product.shippingInformation, product.returnPolicy].filter(Boolean)

  const handleAdd = () => {
    addItem(product)
    setAdded(true)
  }

  return (
    <PageShell>
      <div className="flex min-h-screen w-full justify-center px-4 pb-16 pt-28 md:px-8 md:pt-32">
        <div className="grid h-fit w-full max-w-[1100px] grid-cols-1 overflow-hidden rounded-lg border border-[#B08D57]/40 bg-[#F1E7D0] shadow-xl lg:grid-cols-12">
          {/* LEFT: image */}
          <section className="flex flex-col items-center justify-center gap-4 bg-[#E8DABB] p-6 sm:p-10 lg:col-span-7 lg:p-14">
            <div className="w-full max-w-[460px] overflow-hidden rounded-md border border-[#B08D57]/40 bg-white/60 p-2 shadow-md">
              <img
                src={mainImage}
                alt={product.title}
                className="aspect-square w-full object-cover transition-transform duration-500 hover:scale-105"
              />
            </div>

            {gallery.length > 1 && (
              <div className="flex gap-3">
                {gallery.map((src, i) => (
                  <button
                    key={src}
                    type="button"
                    aria-label={`Show image ${i + 1}`}
                    onClick={() => setActiveImg(i)}
                    className={`h-14 w-14 overflow-hidden rounded border-2 transition-all ${
                      i === activeImg ? 'border-[#B08D57]' : 'border-transparent opacity-60 hover:opacity-100'
                    }`}
                  >
                    <img src={src} alt="" className="h-full w-full object-cover" />
                  </button>
                ))}
              </div>
            )}
          </section>

          {/* RIGHT: info */}
          <section className="flex flex-col justify-center space-y-5 p-6 sm:p-10 lg:col-span-5 lg:p-12">
            <div className="space-y-3">
              <span className="block text-[10px] font-bold uppercase tracking-[0.25em] text-black md:text-black-600 ">
                {product.id}
              </span>
              <span className="block text-[10px] font-bold uppercase tracking-[0.25em] text-[#2A1A1A]/50">
                {product.category}
              </span>
              <h1 className="font-serif-display text-3xl font-medium leading-tight tracking-tight text-[#2A1A1A] md:text-4xl">
                {product.title}
              </h1>
              <div className="h-px w-12 bg-[#B08D57]" />
            </div>

            <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
              <span className="text-2xl font-bold text-[#2A1A1A]">${product.price}</span>
              <span className="text-sm text-[#2A1A1A]/70">★ {product.rating}</span>
              <span
                className={`text-[10px] font-bold uppercase tracking-[0.2em] ${
                  outOfStock ? 'text-[#B3121F]' : 'text-[green]'
                }`}
              >
                {outOfStock ? 'Out of stock' : product.stock <= 5 ? `Only ${product.stock} left` : 'In stock'}
              </span>
            </div>

            <p className="max-w-sm text-sm font-light leading-relaxed text-[#2A1A1A]/75">{product.description}</p>

            {info.length > 0 && (
              <ul className="space-y-1.5 text-xs text-[#2A1A1A]/65">
                {info.map((line) => (
                  <li key={line} className="flex gap-2">
                    <span className="text-[#B08D57]">✦</span>
                    {line}
                  </li>
                ))}
              </ul>
            )}

            <div className="flex w-full max-w-sm flex-col gap-3 pt-4 sm:flex-row">
              <button type="button" onClick={handleAdd} disabled={outOfStock} className={primaryBtn}>
                <svg
                  className="h-[14px] w-[14px] shrink-0 opacity-85"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden="true"
                >
                  <path d="M6 8h12l-1 11a2 2 0 0 1-2 1.8H9a2 2 0 0 1-2-1.8L6 8z" />
                  <path d="M9 8V6.5a3 3 0 0 1 6 0V8" />
                </svg>
                <span>{added ? 'Added ✓' : outOfStock ? 'Sold Out' : 'Add to Cart'}</span>
              </button>

              <Link to="/products" className={secondaryBtn}>
                <span className="text-[10px] opacity-70 transition-transform duration-300 group-hover:-translate-x-1">✦</span>
                <span>Back to shop</span>
              </Link>
            </div>
          </section>
        </div>
      </div>
    </PageShell>
  )
}

function AllDetails() {
  const { id } = useParams()
  return (
    <CartProvider>   
      <Details key={id} />
    </CartProvider>
  )
}

export default AllDetails
