import React from 'react'
import { Link } from 'react-router-dom'
import { CartProvider, useCart } from 'react-use-cart'
import { motion, MotionConfig } from 'framer-motion'
import Navbar from '../Components/Navbar'
import Footer from '../Components/Footer'

const qtyBtn =
  'h-6 w-6 rounded-full border border-[#B08D57]/60 text-sm leading-none text-[#0F3D33] transition-all duration-200 ' +
  'hover:bg-[#150c05] hover:text-[#F1E7D0] active:scale-90 ' +
  'disabled:cursor-not-allowed disabled:opacity-30 disabled:hover:bg-transparent disabled:hover:text-[#0F3D33]'

const parent = {
  hidden: {},
  show: { transition: { staggerChildren: 0.15 } },
}

const pop = {
  hidden: { opacity: 0, scale: 0.85, y: 20 },
  show: {
    opacity: 1,
    scale: 1,
    y: 0,
    transition: { duration: 0.7, ease: [0.22, 1, 0.36, 1] },
  },
}

const fadeUp = {
  hidden: { opacity: 0, y: 12 },
  show: { opacity: 1, y: 0 },
}

function Cart() {
  const { items, updateItemQuantity, removeItem, totalUniqueItems, cartTotal, isEmpty, emptyCart } = useCart()

  return (
    <div className="my-20 flex min-h-screen w-full items-start justify-center px-4 pb-16 pt-28 md:pt-32">
      {/* Main Cart Container Frame */}
      <div className="w-full max-w-[850px] overflow-hidden rounded-lg border border-[#B08D57]/40 bg-[#ffffff] p-5 shadow-xl sm:p-8 md:p-12">
        {/* Header */}
        <div className="mb-8 space-y-3">
          <span className="block text-[15px] font-bold uppercase tracking-[0.25em] text-[#2A1A1A]/50">
            {totalUniqueItems} {totalUniqueItems === 1 ? 'item' : 'items'}
          </span>
          <h2 className="font-serif-display text-2xl font-medium tracking-tight text-[#2A1A1A] md:text-3xl">
            Shopping Cart
          </h2>

          <button onClick={() => emptyCart()} className="button-delete" type="button">
            <span className="button__text">Empty</span>
            <span className="button__icon">
              <svg className="svg" height={512} viewBox="0 0 512 512" width={512} xmlns="http://www.w3.org/2000/svg">
                <title />
                <path
                  d="M112,112l20,320c.95,18.49,14.4,32,32,32H348c17.67,0,30.87-13.51,32-32l20-320"
                  style={{ fill: 'none', stroke: '#fff', strokeLinecap: 'round', strokeLinejoin: 'round', strokeWidth: 32 }}
                />
                <line
                  style={{ stroke: '#fff', strokeLinecap: 'round', strokeMiterlimit: 10, strokeWidth: 32 }}
                  x1={80} x2={432} y1={112} y2={112}
                />
                <path
                  d="M192,112V72h0a23.93,23.93,0,0,1,24-24h80a23.93,23.93,0,0,1,24,24h0v40"
                  style={{ fill: 'none', stroke: '#fff', strokeLinecap: 'round', strokeLinejoin: 'round', strokeWidth: 32 }}
                />
                <line
                  style={{ fill: 'none', stroke: '#fff', strokeLinecap: 'round', strokeLinejoin: 'round', strokeWidth: 32 }}
                  x1={256} x2={256} y1={176} y2={400}
                />
                <line
                  style={{ fill: 'none', stroke: '#fff', strokeLinecap: 'round', strokeLinejoin: 'round', strokeWidth: 32 }}
                  x1={184} x2={192} y1={176} y2={400}
                />
                <line
                  style={{ fill: 'none', stroke: '#fff', strokeLinecap: 'round', strokeLinejoin: 'round', strokeWidth: 32 }}
                  x1={328} x2={320} y1={176} y2={400}
                />
              </svg>
            </span>
          </button>

          <div className="h-px w-12 bg-[#B08D57]" />
        </div>

        {isEmpty ? (
          <motion.div
            variants={parent}
            initial="hidden"
            animate="show"
            className="p-8 py-1 text-center"
          >
            {/* دخول الصورة */}
            <motion.div variants={pop}>
              {/* طفو مستمر */}
              <motion.img
                src="https://i.pinimg.com/1200x/54/46/6b/54466b5efe20095d2be79555eeecfd51.jpg"
                alt="Empty cart"
                className="mx-auto h-auto w-[200px] max-w-full"
                animate={{ y: [0, -10, 0], rotate: [0, 1.5, 0, -1.5, 0] }}
                transition={{ duration: 5, repeat: Infinity, ease: 'easeInOut' }}
              />
            </motion.div>

            <motion.p variants={fadeUp} className="mb-6 mt-6 text-base font-light text-[#0f3d33]/70">
              Your Cart Is Empty.
            </motion.p>

            <motion.div variants={fadeUp}>
              <Link
                to="/products"
                className="text-xs uppercase tracking-[0.2em] text-[#B3121F] transition-colors hover:text-[#4A0A10]"
              >
                ← Browse the collection
              </Link>
            </motion.div>
          </motion.div>
        ) : (
          <>
            {/* Items */}
            <div className="mb-8 space-y-6">
              {items.map((item) => (
                <div
                  key={item.id}
                  className="flex flex-col gap-4 border-b border-[#B08D57]/30 pb-6 sm:flex-row sm:items-center sm:justify-between"
                >
                  {/* Image + name */}
                  <div className="flex min-w-0 items-center gap-4 sm:gap-6">
                    <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded bg-white/60">
                      <img
                        src={item.images[0]}
                        alt={item.title}
                        className="h-12 w-12 object-contain mix-blend-multiply"
                      />
                    </div>
                    <div className="min-w-0">
                      <h3 className="font-serif-display text-sm font-medium leading-tight text-[#2A1A1A] sm:text-base">
                        {item.title}
                      </h3>
                      <p className="mt-0.5 text-[11px] font-light text-[#2A1A1A]/60">{item.brand}</p>
                    </div>
                  </div>

                  {/* Quantity + price + remove */}
                  <div className="flex items-center justify-between gap-4 sm:justify-end sm:gap-8">
                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        aria-label="Decrease quantity"
                        onClick={() => updateItemQuantity(item.id, item.quantity - 1)}
                        disabled={item.quantity <= 1}
                        className={qtyBtn}
                      >
                        -
                      </button>
                      <span className="w-6 select-none text-center text-sm font-bold text-[#2A1A1A]">
                        {item.quantity}
                      </span>
                      <button
                        type="button"
                        aria-label="Increase quantity"
                        onClick={() => updateItemQuantity(item.id, item.quantity + 1)}
                        className={qtyBtn}
                      >
                        +
                      </button>
                    </div>

                    <div className="flex items-center gap-3">
                      <span className="min-w-[4.5rem] text-right text-sm font-bold text-[#2A1A1A]">
                        ${Math.ceil(item.price * item.quantity)}
                      </span>
                      <button
                        type="button"
                        aria-label={`Remove ${item.title}`}
                        onClick={() => removeItem(item.id)}
                        className="cursor-pointer pl-1 text-xs font-light text-[#2A1A1A]/50 transition-colors hover:text-[#B3121F]"
                      >
                        ✕
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Total + Checkout */}
            <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
              <div className="flex items-baseline justify-between gap-3 sm:justify-start">
                <span className="text-[15px] font-bold uppercase tracking-wide text-[#2A1A1A]">Total</span>
                <span className="text-lg font-black text-[#2A1A1A]">${cartTotal.toFixed(2)}</span>
              </div>
              <button
                type="button"
                className="group relative inline-flex h-12 w-full items-center justify-center gap-2 overflow-hidden whitespace-nowrap
                  rounded-full border border-[#B08D57]/60 bg-gradient-to-br from-[#150c05] to-[#150c05] px-10
                  text-xs font-semibold uppercase tracking-[0.15em] text-[#F1E7D0]
                  shadow-[0_5px_14px_rgba(0,0,0,0.6),inset_0_1px_0_rgba(191,232,210,0.12)]
                  transition-all duration-300 hover:-translate-y-0.5 hover:border-[#D4B06A]
                  hover:shadow-[0_8px_20px_rgba(0,0,0,0.6),0_0_24px_rgba(201,166,107,0.5)]
                  active:scale-[0.97] sm:w-auto"
              >
                <span>Checkout</span>
                <span className="text-[10px] opacity-70 transition-all duration-500 group-hover:rotate-90 group-hover:opacity-100">
                  ✦
                </span>
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

function AllCart() {
  return (
    <MotionConfig reducedMotion="user">
      <CartProvider>
        <Navbar />
        <Cart />
        {/* <Footer /> */}
      </CartProvider>
    </MotionConfig>
  )
}

export default AllCart