import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import { createBrowserRouter, RouterProvider, Navigate } from 'react-router-dom';

import { AllData } from './Data/AllData';
import AllCart from './Cart/AllCart';
import ScrollToTop from 'react-scroll-to-top';
import AllAbout from './About/AllAbout';
import AllProducts from './Products/AllProducts';
import AllDetails from './Details/AllDetails';
import AllHelp from './Help/AllHelp'
import AllCheckOut from './checkout/AllCheckOut';
var ahmed = createBrowserRouter([
    {
        path: "/",
        element: <App/>
    }, 
    {
        path: "/cart",
        element: <AllCart/>
    },
    {
        path: "/about",
        element: <AllAbout/>
    },
    {
        path: "/products",
        element: <AllProducts/>
    },
    {
        path: "/details/:id",
        element: <AllDetails/>
    },  
    {
        path: "/help",
        element: <AllHelp/>
    },
    // old / alternate URLs -> Help page
    {
        path: "/shipping",
        element: <Navigate to="/help#shipping" replace/>
    },
    {
        path: "/returns",
        element: <Navigate to="/help#returns" replace/>
    },
    {
        path: "/checkout",
        element:<AllCheckOut/>
    },
  
  
  
       
]);

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
    <AllData>
        <RouterProvider router={ahmed}/>
       <ScrollToTop
  smooth
  component={<span style={{ color: "#F1E7D0", fontSize: 30 }}>↑</span>}
  style={{
    background: "#141010",
    border: "1px solid #B08D57",
    borderRadius: "9999px",
    width: 48,
    height: 48,
    boxShadow: "none",
  }}
/>
    </AllData>
);